async function generateSessionTitle({
  userPrompts,
  maxLength,
  model,
  apiKey,
  headers,
  signal,
  previousTitle
}) {
  const response = await complete(model, {
    messages: [
      {
        role: "user",
        timestamp: Date.now(),
        content: [
          {
            type: "text",
            text: [
              `You are naming a conversation session. Based on the user message below, produce a single short title (max ${maxLength} characters, no quotes). Be specific \u2014 mention the main topic. Use sentence case.`,
              "",
              "User messages:",
              ...userPrompts.map((userPrompt) => `<message>${userPrompt}</message>`),
              previousTitle ? `
The current title is "${previousTitle}" \u2014 refine it if you now have better context, otherwise keep it.` : null
            ].filter(Boolean).join(`
`)
          }
        ]
      }
    ]
  }, { signal, apiKey, headers });
  const title = response.content.filter((content) => content.type === "text").map((content) => content.text.trim()).join("").slice(0, maxLength).replace(/["']/g, "");
  return title || undefined;
}

